def test_extract_php_units_function():
    code = "<?php function hello() { return 1; }"
    units = m.extract_php_units(code)
    assert len(units) == 1
    assert units[0]["type"] == "function"
    assert units[0]["method"] == "hello"
    assert units[0]["class"] is None
    assert units[0]["abstract"] is False


def test_extract_php_units_method():
    code = "<?php class Foo { public function bar() {} }"
    units = m.extract_php_units(code)
    assert len(units) == 1
